import { api, isMockMode } from '../lib/api.js';
import { escapeHtml, longDate } from '../lib/format.js';
import { icon, setTitle } from '../lib/dom.js';

export async function scannerView(path) {
  setTitle('Door scanner');
  if (!isMockMode && !await api.getSession()) return scannerLogin();
  const events = await api.listScanEvents();
  const pathId = path.split('/')[2];
  const selected = events.find((event) => event.id === pathId || event.slug === pathId) || events[0];
  return {
    meta: { section: 'scanner' },
    html: `<main id="main" class="scanner-page" tabindex="-1" style="--event-accent:${selected?.accent || '#e45a2a'}">
      <header class="scanner-head">
        <div><p class="kicker">DOOR / ONLINE</p><h1>Scan a ticket</h1><p>Every result is checked against the selected event on the server.</p></div>
        <label>Checking in for<select data-scan-event>${events.map((event) => `<option value="${event.id}" ${event.id === selected?.id ? 'selected' : ''}>${escapeHtml(event.name)}</option>`).join('')}</select></label>
      </header>
      <section class="scanner-workspace">
        <div class="camera-station">
          <div class="camera-view" data-camera-view>
            <video data-camera-video muted playsinline></video>
            <div class="camera-placeholder">${icon('camera', 42)}<strong>Camera is off</strong><span>Start it when you’re ready to scan.</span></div>
            <div class="scan-frame" aria-hidden="true"><i></i><i></i><i></i><i></i></div>
          </div>
          <div class="camera-actions"><button class="button button--accent" type="button" data-start-camera>${icon('camera')} Start camera</button><button class="button button--outline" type="button" data-stop-camera hidden>Stop camera</button></div>
          <p class="camera-privacy">Video stays in this browser. Only decoded ticket data is sent for verification.</p>
        </div>
        <aside class="scan-side">
          <section class="scan-event-slip"><span>${escapeHtml(selected?.code || '')}</span><div><p class="kicker">SELECTED EVENT</p><h2 data-selected-event>${escapeHtml(selected?.name || '')}</h2><p>${selected ? escapeHtml(longDate(selected.startsAt)) : ''}<br>${escapeHtml(selected?.venue || '')}</p></div></section>
          <section class="manual-scan"><p class="kicker">CAMERA WON’T READ IT?</p><h2>Enter the printed number.</h2><form data-manual-scan><label>Ticket number<input name="ticket" autocomplete="off" autocapitalize="characters" placeholder="LAD26-VIP-7K9M-4Q2P" required></label><button class="button button--ink button--wide" type="submit">Check ticket ${icon('arrow')}</button></form>
          ${isMockMode ? '<div class="test-ticket"><span>VALID DEMO TICKET</span><button type="button" data-use-demo>LAD26-VIP-7K9M-4Q2P</button><small>Choose Lagos After Dark before testing.</small></div>' : ''}</section>
        </aside>
      </section>
      <div class="scan-result-layer" data-scan-result hidden></div>
    </main>`,
    mount: () => mountScanner(events, selected),
  };
}

function scannerLogin() {
  return {
    meta: { section: 'scanner' },
    html: `<main id="main" class="ops-login" tabindex="-1"><section><p class="kicker">DOOR / STAFF ONLY</p><h1>Sign in to open the scanner.</h1><p>Your account will show only its assigned events.</p><form data-scanner-login><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><div class="form-error" data-login-error hidden></div><button class="button button--ink button--wide">Sign in ${icon('arrow')}</button></form></section></main>`,
    mount() {
      const form = document.querySelector('[data-scanner-login]');
      form.addEventListener('submit', async (event) => {
        event.preventDefault(); const button = form.querySelector('button'); const errorBox = form.querySelector('[data-login-error]');
        button.disabled = true; errorBox.hidden = true;
        try { const values = new FormData(form); await api.signIn(values.get('email'), values.get('password')); window.dispatchEvent(new PopStateEvent('popstate')); }
        catch (error) { errorBox.textContent = error.message; errorBox.hidden = false; button.disabled = false; }
      });
    },
  };
}

function mountScanner(events, initial) {
  let eventId = initial?.id;
  let controls;
  let reader;
  let processing = false;
  const video = document.querySelector('[data-camera-video]');
  const view = document.querySelector('[data-camera-view]');
  const start = document.querySelector('[data-start-camera]');
  const stop = document.querySelector('[data-stop-camera]');
  const resultLayer = document.querySelector('[data-scan-result]');

  document.querySelector('[data-scan-event]').addEventListener('change', (changeEvent) => {
    eventId = changeEvent.target.value;
    const event = events.find((item) => item.id === eventId);
    document.querySelector('[data-selected-event]').textContent = event.name;
    document.querySelector('.scanner-page').style.setProperty('--event-accent', event.accent);
  });

  async function verify(value) {
    if (processing) return;
    processing = true;
    try {
      const result = await api.checkIn({ eventId, value });
      showResult(result);
      if (result.valid && navigator.vibrate) navigator.vibrate(100);
      if (!result.valid && navigator.vibrate) navigator.vibrate([120, 70, 120]);
    } catch (error) {
      showResult({ valid: false, reason: 'network_error', message: error.message });
    } finally { processing = false; }
  }

  document.querySelector('[data-manual-scan]').addEventListener('submit', (submitEvent) => {
    submitEvent.preventDefault();
    const input = submitEvent.currentTarget.elements.ticket;
    verify(input.value); input.value = '';
  });
  document.querySelector('[data-use-demo]')?.addEventListener('click', () => {
    document.querySelector('[data-manual-scan] input').value = 'LAD26-VIP-7K9M-4Q2P';
  });

  start.addEventListener('click', async () => {
    start.disabled = true; start.textContent = 'Opening camera…';
    try {
      const { BrowserQRCodeReader } = await import('@zxing/browser');
      reader = new BrowserQRCodeReader(undefined, { delayBetweenScanAttempts: 250 });
      controls = await reader.decodeFromVideoDevice(undefined, video, (result) => {
        if (result && !processing) verify(result.getText());
      });
      view.classList.add('is-live'); start.hidden = true; stop.hidden = false;
    } catch (error) {
      console.error(error);
      start.disabled = false; start.innerHTML = `${icon('camera')} Try camera again`;
      showResult({ valid: false, reason: 'camera_error', message: 'Camera access was unavailable. Use the printed-number field instead.' });
    }
  });
  stop.addEventListener('click', stopCamera);

  function stopCamera() {
    controls?.stop(); reader?.reset?.();
    view.classList.remove('is-live'); start.hidden = false; stop.hidden = true; start.disabled = false; start.innerHTML = `${icon('camera')} Start camera`;
  }

  function showResult(result) {
    const valid = result.valid;
    const reason = reasonCopy(result.reason, result.message);
    resultLayer.hidden = false;
    resultLayer.innerHTML = `<div class="scan-result scan-result--${valid ? 'valid' : 'invalid'}" role="dialog" aria-modal="true" aria-labelledby="scan-result-title">
      <div class="scan-result__icon">${icon(valid ? 'check' : 'close', 52)}</div>
      <p class="kicker">${valid ? 'ADMIT / FIRST SCAN' : 'DO NOT ADMIT'}</p>
      <h2 id="scan-result-title">${valid ? escapeHtml(result.attendeeName) : reason.title}</h2>
      <p>${valid ? `${escapeHtml(result.tier)} · ${escapeHtml(result.ticketNumber)}` : reason.body}</p>
      ${result.checkedInAt ? `<small>Recorded ${escapeHtml(longDate(result.checkedInAt))}</small>` : ''}
      <button class="button ${valid ? 'button--ink' : 'button--paper'} button--wide" type="button" data-next-scan>Scan the next ticket</button>
    </div>`;
    resultLayer.querySelector('[data-next-scan]').addEventListener('click', () => { resultLayer.hidden = true; document.querySelector('[data-manual-scan] input').focus(); });
    resultLayer.querySelector('[data-next-scan]').focus();
  }

  return stopCamera;
}

function reasonCopy(reason, custom) {
  const copy = {
    already_checked_in: ['Already checked in', 'This ticket has already passed through the door.'],
    wrong_event: ['Wrong event', 'This ticket is real, but it belongs to a different event.'],
    ticket_void: ['Ticket is void', 'The box office cancelled or replaced this ticket.'],
    invalid_signature: ['Invalid signature', 'The QR data was altered or did not come from Tixora.'],
    ticket_not_found: ['Ticket not found', 'Check the printed number and selected event, then try again.'],
    event_not_assigned: ['Event not assigned', 'Your staff account cannot check people into this event.'],
    camera_error: ['Camera unavailable', custom],
    network_error: ['Could not reach the server', custom || 'Check the connection before trying again.'],
  };
  const [title, body] = copy[reason] || ['Ticket rejected', custom || 'The server could not validate this ticket.'];
  return { title, body };
}
